import sys
import math

def solve(x, y, k):
    if x == y:
        return 0
    if x > y:
        x, y = y, x
    if k == 0:
        return 0
    if k == 1:
        return 1
    if x == y:
        return k
    if x == y + 1:
        return k + 1
    ans = math.ceil((x + y) / 2)
    ans += solve(x + 1, y, k - 1)
    ans += solve(x - 1, y, k - 1)
    return ans

