            mid = (l + r) // 2
            if books[mid][1] == target:
                return mid
            elif books[mid][1] < target:
                l = mid + 1
            else:
                r = mid - 1
        return -1

    if binary_search(0, len(books) - 1, 0) < len(books) - 1:
        return -1

    if binary_search(0, len(books) - 1, 1) < len(books) - 1:
