def solve(n, arr):
    @lru_cache(None)
    def dfs(i, j):
        if i >= n:
            return 0
        if arr[i] % 2!= arr[j] % 2:
            return float('inf')
        ans = dfs(i + 1, j) + 1
        ans = min(ans, dfs(i + 1, j + 1) + abs(arr[i] * arr[j] - arr[i + 1] - arr[j + 1] + arr[i] * arr[j])
        return ans

    return dfs(0, 0)

