def solve(n, m):
    grid = [[0 for _ in range(m)] for _ in range(n)]

    def get_neighbors(i, j):
        if i == 0 and j == 0:
            return 0
        if i == 0 and j == 0:
            return 1
        if i == 0 or j == 0:
            return 1
        if i == 0:
            return 1 + get_neighbors(i, j - 1)
        if j == 0:
            return 1 + get_neighbors(i - 1, j)
        return 1 + min(get_neighbors(i - 1, j), get_neighbors(i, j - 1))

    def dfs(i, j, cost):
        if i == n - 1 and j == m - 1:
            return cost
        if grid[i][j] == 1:
            return 0
        if i == n - 1:
            return dfs(i, j + 1, cost + 1)
        if j == m - 1:
            return dfs(i + 1, j, cost + 1)
        return min(dfs(i + 1, j, cost + 1), dfs(i, j + 1, cost + 1))

    print(dfs(1, 1, 0))

